#include <stdlib.h>
typedef struct Node{int key,size;struct Node*l,*r;}Node;static int sz(Node*n){return n?n->size:0;}Node*bst_insert(Node*n,int k){if(!n){n=calloc(1,sizeof(*n));n->key=k;n->size=1;return n;}if(k<n->key)n->l=bst_insert(n->l,k);else if(k>n->key)n->r=bst_insert(n->r,k);n->size=1+sz(n->l)+sz(n->r);return n;}int bst_select(Node*n,int rank){if(!n)return 0;int r=sz(n->l)+1;return rank==r?n->key:rank<r?bst_select(n->l,rank):bst_select(n->r,rank-r);}int knapsack(const int*w,const int*v,int n,int cap){int*dp=calloc(cap+1,sizeof(int));for(int i=0;i<n;i++)for(int c=cap;c>=w[i];c--)if(dp[c-w[i]]+v[i]>dp[c])dp[c]=dp[c-w[i]]+v[i];int ans=dp[cap];free(dp);return ans;}
